import torch
P=torch.load('out/steer/surf_pos.pt',weights_only=False)
N=torch.load('out/steer/surf_neg.pt',weights_only=False)
Pa={int(L):v for L,v in P['mean'].items()}
Na={int(L):v for L,v in N['mean'].items()}
# stance direction for reference
th=torch.load('out/steer/think.pt',weights_only=False); dn=torch.load('out/steer/dont.pt',weights_only=False)
T={int(L):v for L,v in th['mean'].items()}; D={int(L):v for L,v in dn['mean'].items()}
import torch
d_stance={L:T[L]-D[L] for L in T}
d_surf={L:Pa[L]-Na[L] for L in Pa}
for L in sorted(Pa):
    cs=torch.nn.functional.cosine_similarity(d_surf[L],d_stance[L],dim=0).item()
    print(L,'||surf||=%.3f'%d_surf[L].norm().item(),'cos(stance,surf)=%.3f'%cs)
"

